12	/**
13	 * Allows for an easy way to "manipulate" the immutable Ast by changing specific nodes and getting back a new Ast
14	 * containing the changed nodes while everything else is the same.
15	 */
16	@PublicApi
17	public class AstTransformer {
18	
19	
20	    public Node transform(Node root, NodeVisitor nodeVisitor) {
21	        assertNotNull(root);
22	        assertNotNull(nodeVisitor);
23	
24	        TraverserVisitor<Node> traverserVisitor = new TraverserVisitor<Node>() {
25	            @Override
26	            public TraversalControl enter(TraverserContext<Node> context) {
27	                return context.thisNode().accept(context, nodeVisitor);
28	            }
29	
30	            @Override
31	            public TraversalControl leave(TraverserContext<Node> context) {
32	                return TraversalControl.CONTINUE;
33	            }
34	        };
35	
36	        TreeTransformer<Node> treeTransformer = new TreeTransformer<>(AST_NODE_ADAPTER);
37	        return treeTransformer.transform(root, traverserVisitor);
38	    }
