32	    private final Function<? super Node, ? extends List<Node>> getChildren;
33	
34	    public NodeTraverser(Map<Class<?>, Object> rootVars, Function<? super Node, ? extends List<Node>> getChildren) {
35	        this.rootVars = rootVars;
36	        this.getChildren = getChildren;
37	    }
