39	    public NodeTraverser() {
40	        this(Collections.emptyMap(), Node::getChildren);
41	    }
42	
43	
44	    /**
45	     * depthFirst traversal with a enter/leave phase.
46	     *
47	     * @param nodeVisitor the visitor of the nodes
48	     * @param root        the root node
49	     *
50	     * @return the accumulation result of this traversal
51	     */
52	    public Object depthFirst(NodeVisitor nodeVisitor, Node root) {
53	        return depthFirst(nodeVisitor, Collections.singleton(root));
54	    }
